-- HK Sprint 6: nội dung khởi tạo cho mô phỏng trận đánh (6 kịch bản, kèm hoạt ảnh) và mini-game (ghép thẻ, sắp xếp dòng thời gian, ô chữ).
-- TẤT CẢ Ở TRẠNG THÁI NHÁP: học sinh chưa thấy gì cho đến khi quản trị tổng cùng giáo viên Lịch sử đối chiếu với sách giáo khoa, công bố hồ sơ trận đánh trong kho lịch sử rồi phát hành.
-- Diễn biến dựa trên các bài "Chiến tranh Nguyên Mông – Đại Việt lần 1/2/3" (vi.wikipedia); chỗ nguồn chép khác nhau (chỉ huy trận Tây Kết, tướng Nguyên dự trận Hàm Tử, vai trò Trần Quốc Toản...) không được khẳng định.
-- Tọa độ trong hoạt ảnh và khu vực bố trí chỉ mang tính minh họa (bán kính rộng). Chạy lại không tạo trùng.

INSERT INTO public.hk_scenarios (battle_id, title, summary, difficulty, content, status)
SELECT b.id, 'Đông Bộ Đầu: phản công quân Mông Cổ', 'Vào vai vua Trần Thái Tông, chọn cách làm yếu quân Mông Cổ trong Thăng Long và phản công đúng lúc, đúng hướng.', 1, $j${"intro":{"situation":"Đầu năm 1258, quân Mông Cổ chiếm kinh thành Thăng Long chỉ sau vài ngày, sau các trận Bình Lệ Nguyên và Phù Lỗ. Nhưng kho lương trong thành trống rỗng, nhà Trần đã cho dân cất giấu lương thực (kế \"vườn không nhà trống\"), việc cướp bóc vùng ngoại vi cũng không mang lại nhiều lương thực. Quân Mông Cổ đang lâm vào tình trạng thiếu thốn.","forces":"Quân Mông Cổ chỉ có kỵ binh và bộ binh, không có thủy binh nên gặp sông ngòi thường khó tiến. Nhà Trần đang trú quân ở Thiên Mạc, bên sông Hồng. Các nguồn ước tính quân số khác nhau nên kịch bản không nêu con số.","objective":"Bạn là vua Trần Thái Tông. Hãy chọn cách làm yếu quân Mông Cổ, hướng tiến công và thời điểm phản công để buộc chúng rời Thăng Long."},"map":{"center":[21,105.9],"zoom":9},"steps":[{"id":"b1","title":"Làm quân Mông Cổ suy yếu","situation":"Quân Mông Cổ đang chiếm kinh thành nhưng thiếu lương. Bạn nên làm gì với lương thực và lực lượng của mình?","links":[],"type":"decision","options":[{"id":"a","text":"Giữ kế \"vườn không nhà trống\", không để giặc cướp được lương thực, chờ chúng kiệt sức rồi phản công.","score":25,"feedback":"Đúng hướng. Theo sử sách, nhà Trần cho dân cất giấu lương thực nên kho lương trong thành trống rỗng và việc cướp bóc ngoại vi không mang lại nhiều lương thực, khiến quân Mông Cổ thiếu thốn.","consequence":"Quân Mông Cổ ngày một đói và suy yếu."},{"id":"b","text":"Mở kho đem lương thực ra thương lượng, xin quân Mông Cổ lui binh.","score":0,"feedback":"Không phù hợp. Nhà Trần không tiếp tế cho giặc: chính việc cất giấu lương thực đã khiến quân Mông Cổ lâm vào cảnh thiếu thốn.","consequence":"Giặc được tiếp sức, cuộc kháng chiến kéo dài."},{"id":"c","text":"Dồn bộ binh đánh thẳng vào kinh thành ngay khi giặc còn sức.","score":5,"feedback":"Chưa phù hợp. Quân Mông Cổ giỏi kỵ binh và bộ binh; chỗ yếu của họ là sông nước và thiếu lương, nên nhà Trần chọn chờ thời cơ rồi mới phản công.","consequence":"Quân Trần chịu tổn thất nặng khi đánh trên đất liền."}]},{"id":"b2","title":"Chọn hướng tiến công","situation":"Quân Mông Cổ không có thủy binh. Bạn sẽ đưa quân tiến đánh bằng đường nào?","links":[],"type":"decision","options":[{"id":"a","text":"Đi lâu thuyền ngược sông Hồng từ nơi trú quân ở Thiên Mạc để đánh vào bến sông sát kinh thành.","score":25,"feedback":"Đúng diễn biến. Vua Trần Thái Tông cùng Thái tử Trần Hoảng ngự lâu thuyền ngược dòng sông, đánh vào nơi quân Mông Cổ yếu nhất là sông nước.","consequence":"Quân Mông Cổ không có cách đối phó trên sông."},{"id":"b","text":"Dàn quân bộ trên cánh đồng ngoài thành để đối đầu kỵ binh Mông Cổ.","score":0,"feedback":"Không phù hợp. Đó là sở trường của kỵ binh Mông Cổ; nhà Trần chọn đường sông, nơi giặc không có thủy binh.","consequence":"Quân Trần mất lợi thế địa hình."},{"id":"c","text":"Rút hẳn về phía nam, bỏ mặc Thăng Long.","score":0,"feedback":"Không phù hợp. Nhà Trần không bỏ cuộc mà chủ động phản công khi thấy thời cơ.","consequence":"Giặc có thời gian củng cố."}]},{"id":"b3","title":"Chọn thời điểm","situation":"Quân Mông Cổ cho rằng quân Trần đã kiệt quệ sau các thất bại trước đó. Khi nào bạn ra tay?","links":[],"type":"decision","options":[{"id":"a","text":"Đánh bất ngờ vào nửa đêm 28/1/1258, khi giặc đang chủ quan.","score":25,"feedback":"Đúng diễn biến. Nửa đêm ngày 28/1/1258 quân Trần bất ngờ tấn công; quân Mông Cổ chủ quan, không kịp trở tay và bị đánh tan ở Đông Bộ Đầu.","consequence":"Quân Mông Cổ tan rã trong đêm."},{"id":"b","text":"Đánh ban ngày để nhìn rõ đội hình giặc.","score":5,"feedback":"Chưa phù hợp. Đánh ban ngày làm mất yếu tố bất ngờ, trong khi chiến thắng đến nhờ giặc chủ quan trước một cuộc tập kích đêm.","consequence":"Giặc kịp dàn đội hình."},{"id":"c","text":"Chờ giặc tự rút đi rồi mới đuổi theo.","score":0,"feedback":"Không phù hợp. Nhà Trần chủ động phản công khi giặc thiếu lương và chủ quan, không chờ giặc tự rút.","consequence":"Mất thời cơ."}]},{"id":"b4","title":"Chọn nơi đánh","situation":"Hãy đặt lâu thuyền của vua Trần vào đúng bến sông nơi cuộc phản công diễn ra.","links":[],"type":"placement","pieces":[{"id":"thuyen","label":"Lâu thuyền của vua Trần"}],"zones":[{"id":"dbd","label":"Bến Đông Bộ Đầu bên sông Hồng, sát Thăng Long","lat":21.04,"lng":105.85,"radius_km":12},{"id":"cuabien","label":"Cửa biển phía đông","lat":20.75,"lng":106.85,"radius_km":25},{"id":"taybac","label":"Vùng núi phía tây bắc","lat":21.65,"lng":105.2,"radius_km":25}],"accept":{"thuyen":["dbd"]},"score":25,"feedback_ok":"Đúng. Trận phản công diễn ra ở Đông Bộ Đầu (nay là dốc Hàng Than, Hà Nội), bên bờ sông Hồng sát kinh thành Thăng Long.","feedback_bad":"Chưa đúng. Trận phản công diễn ra ở Đông Bộ Đầu (nay là dốc Hàng Than, Hà Nội), bên bờ sông Hồng sát kinh thành Thăng Long."}],"animation":{"title":"Diễn biến trận Đông Bộ Đầu (minh họa)","frames":[{"label":"Quân Mông Cổ chiếm Thăng Long, thiếu lương","text":"Quân Trần trú ở Thiên Mạc bên sông Hồng.","units":[{"id":"mc","side":"dich","label":"Quân Mông Cổ","lat":21.03,"lng":105.84},{"id":"tt","side":"tran","label":"Quân Trần ở Thiên Mạc","lat":20.7,"lng":105.96}]},{"label":"Lâu thuyền ngược sông Hồng","text":"Vua Trần Thái Tông cùng Thái tử Trần Hoảng ngự lâu thuyền ngược dòng.","units":[{"id":"mc","side":"dich","label":"Quân Mông Cổ","lat":21.03,"lng":105.84},{"id":"tt","side":"tran","label":"Lâu thuyền của vua Trần","lat":20.88,"lng":105.91}]},{"label":"Nửa đêm 28/1/1258: phản công ở Đông Bộ Đầu","text":"Quân Mông Cổ chủ quan, không kịp trở tay.","units":[{"id":"mc","side":"dich","label":"Quân Mông Cổ","lat":21.03,"lng":105.84},{"id":"tt","side":"tran","label":"Quân Trần đánh vào Đông Bộ Đầu","lat":21.04,"lng":105.855}]},{"label":"Quân Mông Cổ rút khỏi Thăng Long","text":"Quân Mông Cổ rút theo đường bộ bên bờ tả sông Thao, bị thổ quan Hà Bổng tập kích ở Quy Hóa.","units":[{"id":"mc","side":"dich","label":"Quân Mông Cổ rút lui","lat":21.55,"lng":105.25},{"id":"tt","side":"tran","label":"Quân Trần giữ Thăng Long","lat":21.04,"lng":105.85}]}]},"pass_percent":60,"bonus_points":150}$j$::jsonb, 'draft' FROM public.hist_battles b WHERE b.slug = 'dong-bo-dau'
ON CONFLICT (battle_id) DO NOTHING;

INSERT INTO public.hk_scenarios (battle_id, title, summary, difficulty, content, status)
SELECT b.id, 'Hàm Tử: kế ly gián trên sông Hồng', 'Vào vai người chỉ huy quân Trần ở bến Hàm Tử, dùng người Tống cũ và kế ly gián để làm lung lay quân Nguyên.', 2, $j${"intro":{"situation":"Mùa hè năm 1285, quân Trần mở cuộc phản công để giải phóng Thăng Long. Ở vùng sông Hồng, quân Nguyên có nhiều binh lính người Hoa trong đội hình, còn phía quân Trần có những người Tống cũ như Triệu Trung theo giúp. Hai bên giao chiến ở bến Hàm Tử.","forces":"Trần Nhật Duật là chánh tướng ở Hàm Tử. Các nguồn chép khác nhau ở một số chi tiết (như tướng Nguyên nào có mặt ở Hàm Tử), nên kịch bản chỉ dùng những điểm các nguồn nêu nhất quán.","objective":"Bạn là người chỉ huy quân Trần ở Hàm Tử. Hãy tận dụng người Tống cũ và làm lung lay tinh thần đối phương để giành thắng lợi."},"map":{"center":[20.85,105.95],"zoom":10},"steps":[{"id":"h1","title":"Dùng người Tống cũ","situation":"Trong hàng ngũ quân Trần có những người Tống cũ, trong đó có Triệu Trung. Bạn sẽ dùng họ thế nào?","links":[],"type":"decision","options":[{"id":"a","text":"Để người Tống cũ tham chiến trong đội hình, dựng cờ hiệu nhà Tống để tác động tới phía bên kia.","score":25,"feedback":"Đúng hướng. Theo sử sách, quân Trần có cả người Tống cũ như Triệu Trung; theo một số tư liệu, tướng Nguyên là Toa Đô thấy cờ hiệu nhà Tống của Triệu Trung thì lo ngại nhà Tống đã khôi phục.","consequence":"Đối phương bối rối và mất tự tin."},{"id":"b","text":"Chỉ dùng người Việt, không đưa người ngoại quốc vào đội hình.","score":0,"feedback":"Chưa tận dụng được lợi thế mà quân Trần có. Việc đưa cả người Tống cũ vào đội hình góp phần làm đối phương lo ngại.","consequence":"Mất một lợi thế tâm lý."},{"id":"c","text":"Cho người Tống cũ ở lại phía sau làm việc hậu cần.","score":5,"feedback":"Chưa tối ưu. Sự có mặt của họ ngoài mặt trận mới tác động đến binh lính người Hoa bên phía quân Nguyên.","consequence":"Hiệu quả tâm lý giảm đi."}]},{"id":"h2","title":"Làm lung lay binh lính người Hoa","situation":"Trong quân Nguyên có nhiều binh sĩ người Hoa. Bạn làm gì để họ không chiến đấu hết sức?","links":[],"type":"decision","options":[{"id":"a","text":"Bắn thư lên tên, nói rằng quân Trần chỉ đánh người Thát Đát chứ không đánh người Hoa.","score":25,"feedback":"Đúng diễn biến. Quân Trần dùng kế ly gián; nhiều binh sĩ người Hoa trong quân Nguyên không chiến đấu hết sức hoặc đầu hàng.","consequence":"Hàng ngũ quân Nguyên rạn nứt."},{"id":"b","text":"Treo thưởng cho ai giết được nhiều lính người Hoa.","score":0,"feedback":"Không phù hợp. Làm vậy chỉ đẩy họ về phía quân Nguyên; nhà Trần chọn cách phân hóa chứ không đối đầu với tất cả.","consequence":"Binh sĩ người Hoa đoàn kết chống lại."},{"id":"c","text":"Không làm gì thêm, dàn trận đánh thẳng.","score":10,"feedback":"Có thể đánh được nhưng bỏ lỡ cách làm suy yếu đối phương mà nhà Trần đã dùng ở Hàm Tử.","consequence":"Trận đánh trở nên cân sức hơn."}]},{"id":"h3","title":"Bố trí tại bến Hàm Tử","situation":"Hãy đặt lực lượng chính của quân Trần vào đúng nơi diễn ra trận Hàm Tử.","links":[],"type":"placement","pieces":[{"id":"quantran","label":"Quân Trần do Trần Nhật Duật chỉ huy"}],"zones":[{"id":"hamtu","label":"Bến Hàm Tử bên sông Hồng (vùng Khoái Châu)","lat":20.82,"lng":105.97,"radius_km":18},{"id":"bachdang","label":"Cửa sông Bạch Đằng","lat":20.88,"lng":106.75,"radius_km":18},{"id":"vandon","label":"Vùng biển Vân Đồn","lat":21.06,"lng":107.43,"radius_km":25}],"accept":{"quantran":["hamtu"]},"score":25,"feedback_ok":"Đúng. Trận Hàm Tử diễn ra ở bến Hàm Tử trên sông Hồng (vùng Khoái Châu, Hưng Yên ngày nay).","feedback_bad":"Chưa đúng. Trận Hàm Tử diễn ra ở bến Hàm Tử trên sông Hồng (vùng Khoái Châu, Hưng Yên ngày nay), không phải ở vùng cửa biển phía đông."},{"id":"h4","title":"Sau chiến thắng","situation":"Quân Nguyên thua to ở Hàm Tử. Bạn nên làm gì tiếp theo?","links":[],"type":"decision","options":[{"id":"a","text":"Phối hợp các mũi tiến công khác (Chương Dương, Thăng Long), không cho quân Nguyên các nơi hợp binh với nhau.","score":25,"feedback":"Đúng hướng. Trần Nhật Duật được lệnh chặn không cho Toa Đô hợp binh với Thoát Hoan, trong khi hướng Chương Dương – Thăng Long được tiếp tục tiến công.","consequence":"Quân Nguyên bị chia cắt."},{"id":"b","text":"Dừng lại nghỉ ngơi, chờ quân Nguyên tự lui.","score":0,"feedback":"Không phù hợp. Cuộc phản công mùa hè 1285 diễn ra liên tiếp; nhà Trần không dừng lại sau một trận thắng.","consequence":"Quân Nguyên có thời gian hợp binh."}]}],"animation":{"title":"Diễn biến trận Hàm Tử (minh họa)","frames":[{"label":"Quân Nguyên tiến ra vùng sông Hồng","text":"Hai bên đối mặt ở bến Hàm Tử.","units":[{"id":"ng","side":"dich","label":"Quân Nguyên","lat":20.4,"lng":106},{"id":"tr","side":"tran","label":"Quân Trần","lat":20.82,"lng":105.97}]},{"label":"Giao chiến ác liệt ở bến Hàm Tử","text":"Quân Trần dùng kế ly gián với binh lính người Hoa.","units":[{"id":"ng","side":"dich","label":"Quân Nguyên","lat":20.8,"lng":105.99},{"id":"tr","side":"tran","label":"Quân Trần","lat":20.82,"lng":105.97}]},{"label":"Quân Nguyên thua to, lui về sông Thiên Mạc","text":"Quân Nguyên lui về phía nam.","units":[{"id":"ng","side":"dich","label":"Quân Nguyên rút lui","lat":20.7,"lng":105.96},{"id":"tr","side":"tran","label":"Quân Trần","lat":20.82,"lng":105.97}]}]},"pass_percent":60,"bonus_points":150}$j$::jsonb, 'draft' FROM public.hist_battles b WHERE b.slug = 'ham-tu'
ON CONFLICT (battle_id) DO NOTHING;

INSERT INTO public.hk_scenarios (battle_id, title, summary, difficulty, content, status)
SELECT b.id, 'Chương Dương: đại phá chiến thuyền Nguyên', 'Vào vai Trần Quang Khải: cô lập quân Nguyên, đánh vào bến thuyền Chương Dương rồi giải phóng Thăng Long.', 2, $j${"intro":{"situation":"Giữa năm 1285, quân Nguyên ở Thăng Long sắp hết lương, các thuyền chiến đậu ở bến Chương Dương. Quân Trần đang mở cuộc tổng phản công và chuẩn bị giải phóng kinh thành.","forces":"Trần Quang Khải được cử làm chánh tướng, cùng các tướng như Phạm Ngũ Lão. Các nguồn chép khác nhau về vai trò của một số tướng (như Trần Quốc Toản) nên kịch bản không đi vào chi tiết đó.","objective":"Bạn là Trần Quang Khải. Hãy cô lập quân Nguyên, đánh đúng mục tiêu quan trọng nhất và giải phóng Thăng Long."},"map":{"center":[20.95,105.87],"zoom":10},"steps":[{"id":"c1","title":"Chuẩn bị","situation":"Quân Nguyên tập trung ở Thăng Long và các bến thuyền. Trước khi đánh vào mục tiêu chính, bạn làm gì?","links":[],"type":"decision","options":[{"id":"a","text":"Diệt các đồn nhỏ của quân Nguyên, thu thuyền ở các bến đò quanh vùng để cô lập chủ lực.","score":25,"feedback":"Đúng diễn biến. Quân Trần diệt nhiều đồn nhỏ của quân Nguyên, lôi kéo quân người Hoa bỏ hàng ngũ và thu nhiều thuyền ở bến đò.","consequence":"Quân Nguyên mất mắt xích và bị cô lập."},{"id":"b","text":"Bỏ qua các đồn xung quanh, đánh thẳng vào Thăng Long.","score":0,"feedback":"Không phù hợp. Nhà Trần trước hết làm suy yếu và cô lập quân Nguyên ở xung quanh rồi mới tiến đánh mục tiêu chính.","consequence":"Quân Trần bị đánh từ nhiều phía."},{"id":"c","text":"Chờ quân Nguyên tự rút vì hết lương.","score":0,"feedback":"Không phù hợp. Quân Trần chủ động tấn công khi quân Nguyên sắp hết lương chứ không chờ.","consequence":"Quân Nguyên có thời gian chuẩn bị."}]},{"id":"c2","title":"Chọn mục tiêu chính","situation":"Quân Nguyên không ngờ bị tấn công. Bạn đánh vào đâu để gây tổn thất lớn nhất?","links":[],"type":"decision","options":[{"id":"a","text":"Tấn công đoàn chiến thuyền đang đậu ở bến Chương Dương.","score":25,"feedback":"Đúng diễn biến. Quân Nguyên bất ngờ, tan tác bỏ chạy; phần lớn chiến thuyền bị đốt hoặc bị chiếm.","consequence":"Quân Nguyên mất phần lớn chiến thuyền."},{"id":"b","text":"Đánh vào các làng ven sông để cướp lương thực.","score":0,"feedback":"Không phù hợp. Mục tiêu của trận Chương Dương là chiến thuyền của quân Nguyên chứ không phải cướp lương thực.","consequence":"Quân Trần đi chệch mục tiêu."},{"id":"c","text":"Chia nhỏ quân đi đánh nhiều đồn lẻ cùng lúc.","score":5,"feedback":"Chưa phù hợp. Đồn lẻ đã được xử lý ở bước chuẩn bị; đòn quyết định là đánh vào chiến thuyền tại bến Chương Dương.","consequence":"Lực lượng bị phân tán."}]},{"id":"c3","title":"Bố trí tại Chương Dương","situation":"Hãy đặt mũi tiến công của Trần Quang Khải vào đúng bến sông diễn ra trận đánh.","links":[],"type":"placement","pieces":[{"id":"quangkhai","label":"Mũi tiến công của Trần Quang Khải"}],"zones":[{"id":"cd","label":"Bến Chương Dương bên sông Hồng (vùng Thường Tín)","lat":20.87,"lng":105.87,"radius_km":10},{"id":"bd","label":"Cửa sông Bạch Đằng","lat":20.88,"lng":106.75,"radius_km":18},{"id":"vd","label":"Vùng biển Vân Đồn","lat":21.06,"lng":107.43,"radius_km":25}],"accept":{"quangkhai":["cd"]},"score":25,"feedback_ok":"Đúng. Trận Chương Dương diễn ra ở bến Chương Dương bên sông Hồng, thuộc vùng Thường Tín (Hà Nội ngày nay).","feedback_bad":"Chưa đúng. Trận Chương Dương diễn ra ở bến Chương Dương bên sông Hồng, thuộc vùng Thường Tín (Hà Nội ngày nay), phía nam Thăng Long."},{"id":"c4","title":"Sau chiến thắng","situation":"Chiến thuyền của quân Nguyên đã bị tiêu diệt. Bước tiếp theo là gì?","links":[],"type":"decision","options":[{"id":"a","text":"Tiến lên vây và công thành Thăng Long để giải phóng kinh thành.","score":25,"feedback":"Đúng diễn biến. Quân Trần đánh bại đơn vị quân Nguyên ngoài thành rồi vây và công thành; quân Nguyên rút khỏi thành về bờ bắc sông Hồng, khoảng Gia Lâm ngày nay.","consequence":"Thăng Long được giải phóng."},{"id":"b","text":"Dừng lại nghỉ ngơi và để quân Nguyên củng cố trong thành.","score":0,"feedback":"Không phù hợp. Quân Trần đã tiến thẳng lên giải phóng Thăng Long khi quân Nguyên còn mệt mỏi và thiếu thốn.","consequence":"Quân Nguyên có thời gian hồi sức."}]}],"animation":{"title":"Diễn biến trận Chương Dương (minh họa)","frames":[{"label":"Quân Nguyên giữ Thăng Long, thuyền đậu ở Chương Dương","text":"Quân Nguyên sắp hết lương.","units":[{"id":"ng","side":"dich","label":"Quân Nguyên trong thành","lat":21.03,"lng":105.85},{"id":"th","side":"dich","label":"Chiến thuyền ở bến Chương Dương","lat":20.87,"lng":105.87},{"id":"tr","side":"tran","label":"Quân Trần","lat":20.6,"lng":105.9}]},{"label":"Quân Trần diệt đồn nhỏ, thu thuyền ở bến đò","text":"Quân Nguyên bị cô lập.","units":[{"id":"ng","side":"dich","label":"Quân Nguyên trong thành","lat":21.03,"lng":105.85},{"id":"th","side":"dich","label":"Chiến thuyền ở bến Chương Dương","lat":20.87,"lng":105.87},{"id":"tr","side":"tran","label":"Quân Trần","lat":20.74,"lng":105.9}]},{"label":"Tấn công bến Chương Dương","text":"Phần lớn chiến thuyền bị đốt hoặc bị chiếm.","units":[{"id":"ng","side":"dich","label":"Quân Nguyên trong thành","lat":21.03,"lng":105.85},{"id":"tr","side":"tran","label":"Quân Trần đánh Chương Dương","lat":20.87,"lng":105.87}]},{"label":"Giải phóng Thăng Long","text":"Quân Nguyên rút về bờ bắc sông Hồng.","units":[{"id":"ng","side":"dich","label":"Quân Nguyên rút lui","lat":21.05,"lng":105.94},{"id":"tr","side":"tran","label":"Quân Trần vào Thăng Long","lat":21.03,"lng":105.85}]}]},"pass_percent":60,"bonus_points":150}$j$::jsonb, 'draft' FROM public.hist_battles b WHERE b.slug = 'chuong-duong'
ON CONFLICT (battle_id) DO NOTHING;

INSERT INTO public.hk_scenarios (battle_id, title, summary, difficulty, content, status)
SELECT b.id, 'Tây Kết: chặn Toa Đô hợp binh', 'Kịch bản ngắn về trận Tây Kết (24/6/1285): ngăn Toa Đô hợp binh với Thoát Hoan. Cần giáo viên bổ sung và kiểm chứng.', 2, $j${"intro":{"situation":"Sau các chiến thắng ở Hàm Tử và Chương Dương, Thăng Long được giải phóng. Toa Đô, tướng quân Nguyên từ phía nam ra, vẫn còn lực lượng ở vùng sông Thiên Mạc và chưa biết Thoát Hoan đã rút chạy.","forces":"Các nguồn chép khác nhau về người chỉ huy trận Tây Kết, về nơi Toa Đô tử trận và đường trốn của Ô Mã Nhi, nên kịch bản không nêu chỉ huy cụ thể. Hồ sơ trận này trong kho lịch sử còn thiếu mô tả chi tiết, kịch bản ngắn và cần giáo viên Lịch sử bổ sung.","objective":"Bạn là người hoạch định phản công của quân Trần. Hãy chọn cách đánh để lực lượng của Toa Đô không thể hợp binh với Thoát Hoan."},"map":{"center":[20.8,105.97],"zoom":9},"steps":[{"id":"t1","title":"Mục tiêu chiến lược","situation":"Hai đạo quân Nguyên (Thoát Hoan và Toa Đô) đang bị chia cắt. Bạn nên làm gì?","links":[],"type":"decision","options":[{"id":"a","text":"Không cho Toa Đô hợp binh với Thoát Hoan, đánh từng bộ phận.","score":25,"feedback":"Đúng hướng. Theo sử sách, Trần Nhật Duật được lệnh chặn không cho Toa Đô hợp binh với Thoát Hoan.","consequence":"Quân Nguyên bị chia cắt, yếu đi."},{"id":"b","text":"Để hai đạo quân hợp binh rồi quyết chiến một trận lớn.","score":0,"feedback":"Không phù hợp. Nhà Trần chọn đánh từng bộ phận để tránh đối đầu với toàn bộ lực lượng Nguyên.","consequence":"Quân Trần đối mặt lực lượng lớn hơn."},{"id":"c","text":"Chia quân canh giữ mọi nơi, không chủ động đánh.","score":5,"feedback":"Chưa phù hợp. Chủ động tấn công khi đối phương đang bị chia cắt là cách nhà Trần chọn.","consequence":"Mất thời cơ."}]},{"id":"t2","title":"Tận dụng thông tin","situation":"Một tướng Nguyên là Trương Hiển đầu hàng quân Trần và sẵn sàng dẫn đường. Bạn xử lý thế nào?","links":[],"type":"decision","options":[{"id":"a","text":"Dùng người dẫn đường để tập kích đúng chỗ Toa Đô đóng quân ở Tây Kết.","score":25,"feedback":"Đúng theo một số tư liệu: tướng Nguyên là Trương Hiển đầu hàng và dẫn đường cho quân Trần tấn công Toa Đô ở Tây Kết ngày 24/6/1285; quân Nguyên thiệt hại lớn.","consequence":"Quân Trần đánh trúng nơi quân Nguyên không ngờ."},{"id":"b","text":"Từ chối mọi hàng tướng vì sợ gian kế.","score":0,"feedback":"Không phù hợp. Việc tiếp nhận hàng tướng và dùng thông tin của họ đã góp phần vào thắng lợi ở Tây Kết.","consequence":"Mất nguồn thông tin quan trọng."}]}],"animation":{"title":"Diễn biến trận Tây Kết (minh họa)","frames":[{"label":"Toa Đô còn ở vùng sông Thiên Mạc","text":"Toa Đô chưa biết Thoát Hoan đã rút chạy.","units":[{"id":"td","side":"dich","label":"Quân của Toa Đô","lat":20.7,"lng":105.96},{"id":"tr","side":"tran","label":"Quân Trần","lat":20.95,"lng":105.9}]},{"label":"Quân Trần đánh chặn","text":"Ngăn không cho hợp binh với Thoát Hoan.","units":[{"id":"td","side":"dich","label":"Quân của Toa Đô","lat":20.75,"lng":105.97},{"id":"tr","side":"tran","label":"Quân Trần","lat":20.82,"lng":105.97}]},{"label":"Trận Tây Kết, 24/6/1285","text":"Quân Nguyên thiệt hại lớn.","units":[{"id":"td","side":"dich","label":"Quân của Toa Đô bị đánh tan","lat":20.78,"lng":105.98},{"id":"tr","side":"tran","label":"Quân Trần","lat":20.8,"lng":105.97}]}]},"pass_percent":60,"bonus_points":150}$j$::jsonb, 'draft' FROM public.hist_battles b WHERE b.slug = 'tay-ket'
ON CONFLICT (battle_id) DO NOTHING;

INSERT INTO public.hk_scenarios (battle_id, title, summary, difficulty, content, status)
SELECT b.id, 'Vân Đồn: cắt đứt đường tiếp tế', 'Vào vai Trần Khánh Dư: chuộc lỗi bằng cách tập kích đoàn thuyền lương của Trương Văn Hổ.', 2, $j${"intro":{"situation":"Cuối năm 1287, quân Nguyên xâm lược lần thứ ba. Thủy quân của Ô Mã Nhi và Phàn Tiếp tiến sâu vào nội địa, còn đoàn thuyền lương của Trương Văn Hổ đi sau theo đường biển. Nhân Huệ vương Trần Khánh Dư được giao trấn giữ đường biển nhưng đã để quân Nguyên đi qua; Thượng hoàng Trần Thánh Tông sai sứ hỏi tội.","forces":"Quân Nguyên dựa vào đoàn thuyền lương để nuôi đội quân lớn ở Đại Việt. Các nguồn ghi số thuyền và số lương bị mất không giống nhau, nên kịch bản không nêu con số.","objective":"Bạn là Trần Khánh Dư. Hãy lập công chuộc tội bằng cách cắt đứt nguồn lương của quân Nguyên."},"map":{"center":[21,107.3],"zoom":8},"steps":[{"id":"v1","title":"Chuộc lỗi","situation":"Thượng hoàng sai sứ hỏi tội vì để quân Nguyên đi qua. Bạn xử lý thế nào?","links":[],"type":"decision","options":[{"id":"a","text":"Xin khất vài ngày để chuộc tội, rồi tìm cách lập công đánh vào đường tiếp tế của giặc.","score":25,"feedback":"Đúng diễn biến. Theo sử sách, Khánh Dư xin khất vài ngày để chuộc tội, sau đó tập kích đoàn thuyền lương của Trương Văn Hổ.","consequence":"Có cơ hội lập công chuộc tội."},{"id":"b","text":"Bỏ chức, rời vùng biển để tránh bị trị tội.","score":0,"feedback":"Không phù hợp. Khánh Dư ở lại và lập công chuộc tội bằng một trận tập kích quan trọng.","consequence":"Đường biển bị bỏ ngỏ."},{"id":"c","text":"Đem quân đuổi theo thủy quân của Ô Mã Nhi để đánh trực diện.","score":0,"feedback":"Không phù hợp. Chủ lực của Ô Mã Nhi mạnh, trong khi đoàn thuyền lương đi sau không có chủ lực bảo vệ nên là mục tiêu dễ tổn thương hơn.","consequence":"Quân Trần chịu tổn thất lớn."}]},{"id":"v2","title":"Chọn mục tiêu","situation":"Đoàn thuyền lương của Trương Văn Hổ đang tiến vào vùng biển Vân Đồn mà không có chủ lực hộ tống. Bạn sẽ đánh vào đâu?","links":[],"type":"decision","options":[{"id":"a","text":"Tập kích đoàn thuyền lương khi chúng vào vùng biển Vân Đồn.","score":25,"feedback":"Đúng diễn biến. Đầu năm 1288, đoàn thuyền lương bị quân Trần Khánh Dư tập kích; không có chủ lực bảo vệ, đoàn thuyền nhanh chóng bị tiêu diệt.","consequence":"Đoàn thuyền lương bị đánh tan."},{"id":"b","text":"Chờ đoàn thuyền lương cập bờ và hợp với chủ lực rồi mới đánh.","score":0,"feedback":"Không phù hợp. Khi hợp với chủ lực, đoàn thuyền lương sẽ được bảo vệ; thắng lợi đến từ việc đánh đúng lúc nó đi một mình.","consequence":"Quân Nguyên giữ được lương thực."},{"id":"c","text":"Đánh vào các làng ven biển để cướp lương thực.","score":0,"feedback":"Không phù hợp. Mục tiêu của trận Vân Đồn là cắt nguồn tiếp tế của quân Nguyên.","consequence":"Lạc mục tiêu."}]},{"id":"v3","title":"Bố trí phục kích","situation":"Hãy đặt thuyền phục kích của Trần Khánh Dư vào vùng biển diễn ra trận đánh.","links":[],"type":"placement","pieces":[{"id":"phuckich","label":"Thuyền phục kích của Trần Khánh Dư"}],"zones":[{"id":"vandon","label":"Vùng biển Vân Đồn (Quảng Ninh)","lat":21.06,"lng":107.43,"radius_km":28},{"id":"bachdang","label":"Cửa sông Bạch Đằng","lat":20.88,"lng":106.75,"radius_km":18},{"id":"thanglong","label":"Kinh thành Thăng Long","lat":21.03,"lng":105.85,"radius_km":20}],"accept":{"phuckich":["vandon"]},"score":25,"feedback_ok":"Đúng. Trận đánh diễn ra ở vùng biển Vân Đồn (Quảng Ninh ngày nay).","feedback_bad":"Chưa đúng. Đoàn thuyền lương bị tập kích ở vùng biển Vân Đồn (Quảng Ninh ngày nay), trên đường vào Đại Việt."},{"id":"v4","title":"Hệ quả chiến lược","situation":"Đoàn thuyền lương bị tiêu diệt. Việc này mở ra cục diện nào?","links":[],"type":"decision","options":[{"id":"a","text":"Quân Nguyên thiếu lương, rơi vào thế bị động; nhà Trần chuẩn bị đòn quyết định về sau.","score":25,"feedback":"Đúng đánh giá của sử sách: sau Vân Đồn, quân Nguyên thiếu lương và rơi vào thế bị động, mở đường cho thắng lợi ở Bạch Đằng.","consequence":"Quân Nguyên buộc phải tính chuyện rút lui."},{"id":"b","text":"Quân Nguyên vẫn đủ lương và tiếp tục tiến công mạnh.","score":0,"feedback":"Không đúng. Thuyền lương của quân Nguyên mất hoàn toàn nên họ thiếu lương nghiêm trọng.","consequence":"Đánh giá sai tình hình."}]}],"animation":{"title":"Diễn biến trận Vân Đồn (minh họa)","frames":[{"label":"Thủy quân Nguyên tiến sâu, đoàn thuyền lương đi sau","text":"Trần Khánh Dư trấn giữ đường biển.","units":[{"id":"om","side":"dich","label":"Thủy quân Ô Mã Nhi","lat":21,"lng":106.5},{"id":"lg","side":"dich","label":"Đoàn thuyền lương Trương Văn Hổ","lat":20.7,"lng":108.3},{"id":"kd","side":"tran","label":"Quân Trần Khánh Dư","lat":21.06,"lng":107.43}]},{"label":"Tập kích đoàn thuyền lương ở Vân Đồn","text":"Đoàn thuyền không có chủ lực bảo vệ.","units":[{"id":"lg","side":"dich","label":"Đoàn thuyền lương bị tập kích","lat":21,"lng":107.5},{"id":"kd","side":"tran","label":"Quân Trần Khánh Dư","lat":21.06,"lng":107.45}]},{"label":"Trương Văn Hổ đổ thóc xuống biển, bỏ chạy","text":"Thuyền lương của quân Nguyên mất hoàn toàn.","units":[{"id":"lg","side":"dich","label":"Trương Văn Hổ bỏ chạy","lat":20.5,"lng":108.8},{"id":"kd","side":"tran","label":"Quân Trần Khánh Dư","lat":21.06,"lng":107.45}]}]},"pass_percent":60,"bonus_points":150}$j$::jsonb, 'draft' FROM public.hist_battles b WHERE b.slug = 'van-don'
ON CONFLICT (battle_id) DO NOTHING;

INSERT INTO public.hk_scenarios (battle_id, title, summary, difficulty, content, status)
SELECT b.id, 'Bạch Đằng: bãi cọc ngầm và con nước', 'Vào vai Quốc công Tiết chế Trần Hưng Đạo: đóng cọc, nhử thuyền giặc, đợi nước triều rút rồi tổng tấn công.', 3, $j${"intro":{"situation":"Tháng 4/1288, quân Nguyên thiếu lương nên phải rút khỏi Thăng Long. Thủy quân do Ô Mã Nhi chỉ huy, cùng Phàn Tiếp, rút về theo đường sông Bạch Đằng để ra biển. Đây là cơ hội để tiêu diệt đội thủy quân mạnh nhất của giặc.","forces":"Quân Đại Việt có bộ binh, thủy quân và dân binh địa phương. Số quân hai bên theo các nguồn khác nhau nên kịch bản không nêu con số.","objective":"Bạn là Quốc công Tiết chế Trần Hưng Đạo. Hãy bố trí trận địa, nhử địch và chọn đúng lúc tổng tấn công để tiêu diệt thủy quân Nguyên."},"map":{"center":[20.95,106.6],"zoom":9},"steps":[{"id":"d1","title":"Chuẩn bị trận địa","situation":"Thủy quân Nguyên sẽ rút theo sông Bạch Đằng. Bạn bố trí trận địa như thế nào?","links":[],"type":"decision","options":[{"id":"a","text":"Đóng cọc ngầm ở lòng sông, bố trí bộ binh phục hai bên bờ và thủy quân ẩn ở các sông nhánh.","score":25,"feedback":"Đúng. Quân Đại Việt đóng cọc ngầm ở lòng sông, bộ binh trú tại Tràng Kênh chờ đánh sườn, một lực lượng khác phục trong rừng bên tả ngạn, thủy quân ẩn trên các sông nhánh.","consequence":"Địch lọt vào thế trận được chuẩn bị sẵn."},{"id":"b","text":"Dàn kỵ binh chặn địch ở hai bên bờ sông.","score":0,"feedback":"Không phù hợp. Đối thủ là thủy quân; thắng lợi đến từ sự kết hợp giữa bãi cọc ngầm ở lòng sông và các đạo quân phục kích hai bên.","consequence":"Quân Trần không cản được thuyền giặc."},{"id":"c","text":"Dàn chiến thuyền chặn ngang cửa sông và đánh trực diện.","score":5,"feedback":"Chưa phù hợp. Lịch sử cho thấy quân Trần không chọn đánh trực diện mà dùng thế trận phục kích kết hợp bãi cọc ngầm.","consequence":"Quân Trần mất lợi thế địa hình."}]},{"id":"d2","title":"Nhử địch vào bãi cọc","situation":"Thủy quân Nguyên đang tiến ra cửa sông. Bạn làm sao để chúng đi vào bãi cọc?","links":[],"type":"decision","options":[{"id":"a","text":"Dùng thuyền nhẹ giả thua, nhử thủy quân Nguyên đuổi theo vào bãi cọc khi nước triều lên.","score":25,"feedback":"Đúng. Thủy quân Nguyên đuổi theo thủy quân Việt rồi va vào cọc và bị chặn lại; khi triều lên, bãi cọc ngầm bị nước che khuất.","consequence":"Thuyền địch mắc vào bãi cọc."},{"id":"b","text":"Cho toàn bộ chiến thuyền Việt xuất hiện công khai để dọa địch rút lui.","score":0,"feedback":"Không phù hợp. Nếu lộ thế trận, địch sẽ tránh khỏi bãi cọc thay vì lao vào.","consequence":"Địch cảnh giác và đổi hướng."},{"id":"c","text":"Chờ địch tự tiến, không dùng mồi nhử.","score":5,"feedback":"Chưa phù hợp. Nhà Trần chủ động dùng thuyền nhẹ nhử địch đi qua đúng vị trí đã bố trí cọc.","consequence":"Mất tính chủ động."}]},{"id":"d3","title":"Chọn lúc tổng tấn công","situation":"Thuyền Nguyên đã vào khu vực cọc. Khi nào bạn ra lệnh tổng tấn công?","links":[],"type":"decision","options":[{"id":"a","text":"Đợi nước triều rút để thuyền giặc va vào cọc, ùn tắc, rồi mới đổ ra từ nhiều hướng.","score":25,"feedback":"Đúng. Khi nước triều rút số thuyền va vào cọc tăng lên, đoàn thuyền ùn tắc, không thoát ra biển được; sáng 9/4/1288 quân Đại Việt đổ ra từ nhiều hướng, vua Trần và Trần Hưng Đạo trực tiếp cầm quân.","consequence":"Thủy quân Nguyên bị tiêu diệt."},{"id":"b","text":"Tấn công ngay khi triều đang lên, lúc thuyền giặc còn xoay xở được.","score":0,"feedback":"Không phù hợp. Khi triều còn lên, thuyền giặc chưa mắc cọc nên vẫn xoay xở được; thắng lợi đến khi nước triều rút.","consequence":"Địch kịp rút ra biển."},{"id":"c","text":"Hạ lệnh rút lui để bảo toàn lực lượng.","score":0,"feedback":"Không phù hợp. Đây là thời cơ quyết định để tiêu diệt thủy quân Nguyên.","consequence":"Mất thời cơ."}]},{"id":"d4","title":"Xử lý cánh quân đổ bộ","situation":"Phàn Tiếp cho quân đổ bộ chiếm núi Tràng Kênh. Bạn đối phó thế nào?","links":[],"type":"decision","options":[{"id":"a","text":"Dùng bộ binh phục sẵn ở Tràng Kênh vây đánh, đẩy chúng xuống sông.","score":25,"feedback":"Đúng diễn biến. Phàn Tiếp cho quân đổ bộ chiếm núi Tràng Kênh nhưng bị phục binh vây đánh và đẩy xuống sông.","consequence":"Cánh quân đổ bộ bị tiêu diệt."},{"id":"b","text":"Bỏ mặc cánh quân đổ bộ để tập trung vào thuyền.","score":0,"feedback":"Không phù hợp. Bộ binh phục ở Tràng Kênh chính là để chặn cánh quân đổ bộ và đánh vào sườn địch.","consequence":"Địch có chỗ đứng trên bờ."}]},{"id":"d5","title":"Bố trí trận địa trên bản đồ","situation":"Hãy đặt bãi cọc ngầm và đạo bộ binh phục kích vào đúng khu vực trận địa.","links":[],"type":"placement","pieces":[{"id":"coc","label":"Bãi cọc ngầm"},{"id":"phucbinh","label":"Bộ binh phục kích ở Tràng Kênh"}],"zones":[{"id":"bachdang","label":"Vùng sông Bạch Đằng – Tràng Kênh (Hải Phòng – Quảng Ninh)","lat":20.88,"lng":106.7,"radius_km":20},{"id":"vankiep","label":"Vạn Kiếp (Hải Dương)","lat":21.12,"lng":106.4,"radius_km":14},{"id":"thanglong","label":"Kinh thành Thăng Long","lat":21.03,"lng":105.85,"radius_km":20},{"id":"vandon","label":"Vùng biển Vân Đồn","lat":21.06,"lng":107.43,"radius_km":20}],"accept":{"coc":["bachdang"],"phucbinh":["bachdang"]},"score":25,"feedback_ok":"Đúng. Bãi cọc ngầm nằm ở lòng sông Bạch Đằng và bộ binh phục ở Tràng Kênh, cùng vùng cửa sông giữa Hải Phòng và Quảng Ninh ngày nay.","feedback_bad":"Chưa đúng. Trận địa ở sông Bạch Đằng và vùng Tràng Kênh, giữa Hải Phòng và Quảng Ninh ngày nay, chứ không ở kinh thành hay vùng biển Vân Đồn."}],"animation":{"title":"Diễn biến trận Bạch Đằng, 9/4/1288 (minh họa)","frames":[{"label":"Thủy quân Nguyên rút theo sông Bạch Đằng","text":"Trận địa cọc ngầm và quân phục kích đã sẵn sàng.","units":[{"id":"ng","side":"dich","label":"Thủy quân Ô Mã Nhi","lat":21.08,"lng":106.4},{"id":"coc","side":"tran","label":"Bãi cọc ngầm","lat":20.88,"lng":106.7},{"id":"pb","side":"tran","label":"Bộ binh phục ở Tràng Kênh","lat":20.85,"lng":106.65}]},{"label":"Thuyền nhẹ nhử địch","text":"Thủy quân Nguyên đuổi theo.","units":[{"id":"ng","side":"dich","label":"Thủy quân Nguyên","lat":20.97,"lng":106.55},{"id":"tn","side":"tran","label":"Thuyền nhẹ của quân Trần","lat":20.92,"lng":106.62},{"id":"coc","side":"tran","label":"Bãi cọc ngầm","lat":20.88,"lng":106.7}]},{"label":"Nước triều rút, thuyền Nguyên va cọc","text":"Đoàn thuyền ùn tắc.","units":[{"id":"ng","side":"dich","label":"Thuyền Nguyên mắc cọc","lat":20.88,"lng":106.7},{"id":"pb","side":"tran","label":"Bộ binh phục ở Tràng Kênh","lat":20.85,"lng":106.65}]},{"label":"Tổng tấn công, thủy quân Nguyên bị tiêu diệt","text":"Ô Mã Nhi và Phàn Tiếp bị bắt.","units":[{"id":"ng","side":"dich","label":"Thủy quân Nguyên tan rã","lat":20.88,"lng":106.72},{"id":"tr","side":"tran","label":"Quân Trần từ nhiều hướng","lat":20.9,"lng":106.74}]}]},"pass_percent":60,"bonus_points":150}$j$::jsonb, 'draft' FROM public.hist_battles b WHERE b.slug = 'bach-dang'
ON CONFLICT (battle_id) DO NOTHING;

INSERT INTO public.hk_minigames (kind, title, description, campaign_id, params, seconds, points, status)
SELECT 'match', 'Ai gắn với trận nào?', 'Ghép nhân vật với trận đánh hoặc sự kiện gắn với họ.', (SELECT id FROM public.hist_campaigns WHERE slug = 'khang-chien-lan-2-1285'), $j${"left_label":"Nhân vật","right_label":"Trận đánh","pairs":[{"id":"p1","left":"Trần Thái Tông","right":"Phản công ở Đông Bộ Đầu (1258)"},{"id":"p2","left":"Hà Bổng","right":"Tập kích quân Mông Cổ ở Quy Hóa (1258)"},{"id":"p3","left":"Trần Nhật Duật","right":"Trận Hàm Tử (1285)"},{"id":"p4","left":"Trần Quang Khải","right":"Trận Chương Dương (1285)"},{"id":"p5","left":"Trần Khánh Dư","right":"Trận Vân Đồn (1288)"},{"id":"p6","left":"Trần Hưng Đạo","right":"Trận Bạch Đằng (1288)"}]}$j$::jsonb, 120, 100, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM public.hk_minigames WHERE kind = 'match' AND title = 'Ai gắn với trận nào?');

INSERT INTO public.hk_minigames (kind, title, description, campaign_id, params, seconds, points, status)
SELECT 'match', 'Địa danh và sự kiện', 'Ghép địa danh với điều đã xảy ra tại đó.', NULL, $j${"left_label":"Địa danh","right_label":"Sự kiện","pairs":[{"id":"p1","left":"Đông Bộ Đầu","right":"Quân Trần phản công quân Mông Cổ nửa đêm 28/1/1258"},{"id":"p2","left":"Chương Dương","right":"Phần lớn chiến thuyền Nguyên bị đốt hoặc bị chiếm"},{"id":"p3","left":"Hàm Tử","right":"Kế ly gián làm binh lính người Hoa trong quân Nguyên lung lay"},{"id":"p4","left":"Vân Đồn","right":"Đoàn thuyền lương của Trương Văn Hổ bị tập kích"},{"id":"p5","left":"Bạch Đằng","right":"Bãi cọc ngầm đánh tan thủy quân Nguyên năm 1288"}]}$j$::jsonb, 120, 100, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM public.hk_minigames WHERE kind = 'match' AND title = 'Địa danh và sự kiện');

INSERT INTO public.hk_minigames (kind, title, description, campaign_id, params, seconds, points, status)
SELECT 'timeline', 'Sắp xếp các mốc kháng chiến', 'Kéo các sự kiện về đúng thứ tự thời gian, từ sớm đến muộn.', NULL, $j${"items":[{"id":"e1","text":"Trận Bình Lệ Nguyên","key":12580117,"when":"17/1/1258"},{"id":"e2","text":"Phản công ở Đông Bộ Đầu","key":12580128,"when":"Nửa đêm 28/1/1258"},{"id":"e3","text":"Quân Nguyên chiếm Thăng Long","key":12850217,"when":"17–18/2/1285"},{"id":"e4","text":"Trận Tây Kết","key":12850624,"when":"24/6/1285"},{"id":"e5","text":"Trận Vân Đồn","key":12871231,"when":"Cuối 12/1287 – đầu 1/1288"},{"id":"e6","text":"Trận Bạch Đằng","key":12880409,"when":"9/4/1288"}]}$j$::jsonb, 120, 100, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM public.hk_minigames WHERE kind = 'timeline' AND title = 'Sắp xếp các mốc kháng chiến');

INSERT INTO public.hk_minigames (kind, title, description, campaign_id, params, seconds, points, status)
SELECT 'crossword', 'Ô chữ địa danh kháng chiến', 'Giải ô chữ về những địa danh nổi tiếng trong ba lần kháng chiến.', NULL, $j${"words":[{"id":"w1","answer":"BẠCH ĐẰNG","clue":"Con sông nơi năm 1288 quân Trần đóng cọc ngầm, đánh tan thủy quân Nguyên."},{"id":"w2","answer":"ĐÔNG BỘ ĐẦU","clue":"Bến sông bên Thăng Long (nay là dốc Hàng Than) nơi quân Trần phản công quân Mông Cổ năm 1258."},{"id":"w3","answer":"VÂN ĐỒN","clue":"Cửa biển nơi đoàn thuyền lương của Trương Văn Hổ bị tập kích đầu năm 1288."},{"id":"w4","answer":"HÀM TỬ","clue":"Bến sông Hồng nơi quân Trần giành thắng lợi năm 1285, dùng kế ly gián với lính người Hoa."},{"id":"w5","answer":"CHƯƠNG DƯƠNG","clue":"Bến sông nơi chiến thuyền Nguyên bị đốt hoặc bị chiếm năm 1285."},{"id":"w6","answer":"THĂNG LONG","clue":"Kinh đô nhà Trần, nay là Hà Nội."}],"layout":{"rows":10,"cols":11,"words":[{"id":"w2","row":0,"col":2,"dir":"down","length":9,"number":1},{"id":"w6","row":0,"col":5,"dir":"down","length":9,"number":2},{"id":"w1","row":1,"col":10,"dir":"down","length":8,"number":3},{"id":"w4","row":2,"col":4,"dir":"across","length":5,"number":4},{"id":"w3","row":4,"col":8,"dir":"down","length":6,"number":5},{"id":"w5","row":8,"col":0,"dir":"across","length":11,"number":6}]}}$j$::jsonb, 300, 100, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM public.hk_minigames WHERE kind = 'crossword' AND title = 'Ô chữ địa danh kháng chiến');
